import { tv, type VariantProps } from "@/lib/beton/tv";

export const spinner = tv({
  slots: {
    root: "inline-flex items-center gap-2 text-foreground",
    icon: "shrink-0 animate-spin-stepped fill-current motion-reduce:animate-none",
    label: "font-mono text-sm font-bold uppercase",
  },
  variants: {
    size: {
      sm: { icon: "size-4" },
      md: { icon: "size-6" },
      lg: { icon: "size-10", label: "text-base" },
    },
    showLabel: {
      true: {},
      false: { label: "sr-only" },
    },
  },
  defaultVariants: {
    size: "md",
    showLabel: false,
  },
});

export type SpinnerVariants = VariantProps<typeof spinner>;

import { spinner, type SpinnerVariants } from "@/lib/beton/recipes/spinner.recipe";
import type { ComponentProps } from "react";

export interface SpinnerProps extends Omit<ComponentProps<"span">, "children">, SpinnerVariants {
  /** Text announced to assistive technology. Visible when `showLabel` is set. */
  label?: string;
}

const BLOCKS = [0, 1, 2, 3, 4, 5, 6, 7];

export function Spinner({
  size = "md",
  showLabel = false,
  label = "Loading",
  className,
  ...props
}: SpinnerProps) {
  const styles = spinner({ size, showLabel });
  return (
    <span role="status" data-size={size} {...props} className={styles.root({ class: className })}>
      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" className={styles.icon()}>
        {BLOCKS.map((i) => (
          <rect
            key={i}
            x="10.5"
            y="1"
            width="3"
            height="6"
            transform={`rotate(${i * 45} 12 12)`}
            opacity={i === 0 ? 1 : 0.2 + (i / BLOCKS.length) * 0.8}
          />
        ))}
      </svg>
      <span className={styles.label()}>{label}</span>
    </span>
  );
}
